CREATE TABLE products (id BIGINT AUTO_INCREMENT PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, slug VARCHAR(100) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, price INT NOT NULL, original_price INT NOT NULL, description VARCHAR(2000), details VARCHAR(4000), composition VARCHAR(255), gsm INT NOT NULL, new_in BOOLEAN NOT NULL, sort_order INT NOT NULL, collection_order INT NOT NULL DEFAULT 0, status VARCHAR(255));
CREATE TABLE product_collections (product_id BIGINT NOT NULL, position INT NOT NULL, value VARCHAR(255), PRIMARY KEY(product_id,position), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE product_colours (product_id BIGINT NOT NULL, position INT NOT NULL, value VARCHAR(255), PRIMARY KEY(product_id,position), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE product_sizes (product_id BIGINT NOT NULL, position INT NOT NULL, value VARCHAR(255), PRIMARY KEY(product_id,position), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE product_media (product_id BIGINT NOT NULL, position INT NOT NULL, url VARCHAR(255), alt VARCHAR(255), colour VARCHAR(255), kind VARCHAR(255), contain_image BOOLEAN NOT NULL, PRIMARY KEY(product_id,position), FOREIGN KEY(product_id) REFERENCES products(id));

